(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.2)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.18)*8 + Math.sin((x+y)*0.013-t*0.16)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.07, 2.1, 0.9],
    [320+Math.cos(t*0.45)*110, 170+Math.sin(t*0.6)*55, 0.09, 1.8, 1.1],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.42+1)*95, 0.055, 2.5, 0.8],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*65, 0.11, 1.4, 1.2],
    [380+Math.sin(t*0.38+4)*100, 50+Math.cos(t*0.8+2)*75, 0.065, 2.8, 0.7],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 1.0],
    [60+Math.sin(t*0.55+3)*70, 100+Math.cos(t*0.65+4)*50, 0.1, 1.6, 1.15],
    [420+Math.cos(t*0.42+2)*80, 140+Math.sin(t*0.58+1)*60, 0.075, 2.3, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const decay = Math.exp(-d*0.003)*w;
    aS += (Math.sin(d*f-t*sp)+Math.sin(d*f*1.618-t*sp*0.8))*decay;
    iS += (Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.cos(d*f*0.5-t*sp*0.4+2.1))*decay;
    cS += Math.sin(d*f*0.3+Math.atan2(sy-sY,sx-sX)*2-t*sp*0.3)*decay*0.5;
  }
  const act=aS/8, inh=iS/8, cou=cS/8;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2
    + Math.sin((sx+sy)*0.1+t*2.2)*0.2 + Math.sin((sx-sy)*0.09-t*1.8)*0.2
    + Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.05-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
