    + Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const lap = (Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.11+t)*0.4
    +Math.cos((sx-sy)*0.09-t*0.8)*0.3)*1.2;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + cou*0.4)*2.5);
  const cell = Math.tanh((lap + Math.sin(reaction*3)*0.3)*1.3)*0.25;
  const feedback = Math.tanh((reaction - cell*0.5)*1.8)*0.15;
  const blend = reaction*0.6 + cell*0.25 + feedback*0.15;
  const v = blend*0.5+0.5;
  const edge = 1.0-Math.pow(Math.abs(blend),8)*0.4;
  const pal = [
    [6,12,52],[12,42,88],[18,78,118],[24,128,138],
    [65,168,148],[145,195,125],[210,195,75],
    [228,155,62],[215,105,72],[185,65,78],
    [130,38,72],[65,18,58],[22,10,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(spiral)*0.08;
  const glow=Math.pow(Math.max(0,reaction),3)*0.6;
  return [
    Math.min(255,((r0+lum*40+glow*60)*lum*edge)|0),
    Math.min(255,((g0+lum*25+glow*45)*lum*edge)|0),
    Math.min(255,((b0+lum*15+glow*70)*lum*edge)|0)
  ];
}
